1	// Package review — see env.go for package-level rationale.
2	//
3	// run.go implements the single-agent orchestrator. CU8 generalizes
4	// to N agents with a sibling RunMulti that re-uses the same
5	// AgentRun classification and Sink fan-out.
6	package review
7	
8	import (
9		"context"
10		"errors"
11		"fmt"
12		"time"
13	
14		reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
15	)
16	
17	type reviewerRunMetadata interface {
18		ActualAgentName() string
19		ModelName() string
20	}
21	
22	func reviewerActualAgentName(r reviewtypes.AgentReviewer) string {
23		if meta, ok := r.(reviewerRunMetadata); ok && meta.ActualAgentName() != "" {
24			return meta.ActualAgentName()
25		}
26		return r.Name()
27	}
28	
29	func reviewerModelName(r reviewtypes.AgentReviewer) string {
30		if meta, ok := r.(reviewerRunMetadata); ok {
31			return meta.ModelName()
32		}
33		return ""
34	}
35	
36	// defaultInspectorTimeout bounds a single inspector's run when the caller
37	// doesn't set RunConfig.InspectorTimeout. A stuck agent is cancelled (its
38	// process killed) and marked failed rather than hanging the review forever.
39	const defaultInspectorTimeout = 10 * time.Minute
40	
41	// inspectorTimeout resolves the effective per-inspector timeout, distinguishing
42	// the three RunConfig.InspectorTimeout states the zero value alone can't:
43	//   - positive: use it.
44	//   - zero (unset): use defaultInspectorTimeout.
45	//   - negative: disabled — return 0, and callers treat 0 as "no timeout".
46	func inspectorTimeout(cfg reviewtypes.RunConfig) time.Duration {
47		switch {
48		case cfg.InspectorTimeout > 0:
49			return cfg.InspectorTimeout
50		case cfg.InspectorTimeout < 0:
51			return 0
52		default:
53			return defaultInspectorTimeout
54		}
55	}
56	
57	// timedOutError reports the per-inspector timeout as a user-facing error.
58	func timedOutError(agent string, timeout time.Duration) error {
59		return fmt.Errorf("review agent %s timed out after %s", agent, timeout)
60	}
61	
62	// Run executes a single-agent review. Events from the agent are forwarded
63	// to all sinks via AgentEvent as they arrive; on completion, RunFinished
64	// is called on each sink with the populated RunSummary.
65	//
66	// Returns the summary plus the agent's terminal error (nil on clean exit,
67	// ctx.Err() on cancellation, an error wrapping *exec.ExitError on non-zero
68	// exit, or an agent-level error when the event stream reports failure).
69	// Callers can inspect both: the summary is always populated even on error.
70	func Run(
71		ctx context.Context,
72		reviewer reviewtypes.AgentReviewer,
73		cfg reviewtypes.RunConfig,
74		sinks []reviewtypes.Sink,
75	) (reviewtypes.RunSummary, error) {
76		started := time.Now()
77		displayName := reviewer.Name()
78		agentName := reviewerActualAgentName(reviewer)
79		modelName := reviewerModelName(reviewer)
80		if modelName == "" {
81			modelName = cfg.Model
82		}
83	
84		// Bound the inspector so a stuck agent can't hang the review forever (unless
85		// the timeout is disabled). The deadline applies only to this agent;
86		// cancellation kills its process. defer runs at function return (after
87		// proc.Wait below), so agentCtx stays live for the whole run; deferring here
88		// — not after Start — also releases the timer on the Start-error path.
89		timeout := inspectorTimeout(cfg)
90		agentCtx := ctx
91		var cancelAgent context.CancelFunc = func() {}
92		if timeout > 0 {
93			agentCtx, cancelAgent = context.WithTimeout(ctx, timeout)
94		}
95		defer cancelAgent()
96	
97		proc, err := reviewer.Start(agentCtx, cfg)
98		if err != nil {
99			// Construction failed — classify (cancellation vs failure), fan out, return.
100			// No event-stream signals available since Start failed before producing any.
101			finished := time.Now()
102			status := classifyStatus(ctx, err, eventOutcome{})
103			summary := reviewtypes.RunSummary{
104				StartedAt:  started,
105				FinishedAt: finished,
106				Cancelled:  status == reviewtypes.AgentStatusCancelled,
107				AgentRuns: []reviewtypes.AgentRun{{
108					Name:      displayName,
109					AgentName: agentName,
110					Model:     modelName,
111					Status:    status,
112					Err:       err,
113					StartedAt: started,
114					Duration:  finished.Sub(started),
115				}},
116			}
117			for _, sink := range sinks {
118				sink.RunFinished(summary)
119			}
120			return summary, err //nolint:wrapcheck // interface-boundary passthrough; wrapping breaks classifyStatus's ctx.Err() identity check for cancelled-during-Start scenarios
121		}
122	
123		var (
124			buffer       []reviewtypes.Event
125			tokens       reviewtypes.Tokens
126			finishedSeen bool // saw Finished{...} event from the parser
127			finishedOk   bool // its Success field
128			sawRunError  bool // saw at least one RunError event
129			firstRunErr  error
130		)
131		for ev := range proc.Events() {
132			buffer = append(buffer, ev)
133			switch e := ev.(type) {
134			case reviewtypes.Tokens:
135				tokens = e // Tokens is cumulative per CU2 contract — overwrite.
136			case reviewtypes.Finished:
137				finishedSeen = true
138				finishedOk = e.Success
139			case reviewtypes.RunError:
140				sawRunError = true
141				if firstRunErr == nil {
142					firstRunErr = e.Err
143				}
144			}
145			for _, sink := range sinks {
146				sink.AgentEvent(displayName, ev)
147			}
148		}
149	
150		waitErr := proc.Wait()
151		finished := time.Now()
152		// Classify from waitErr, the termination cause captured when Wait returned:
153		// the Process contract returns DeadlineExceeded when the process was killed
154		// by this inspector's deadline and Canceled on a parent cancellation (user
155		// Ctrl+C). Using waitErr instead of re-sampling agentCtx avoids a deadline
156		// firing in the gap after a natural completion (waitErr == nil) and producing
157		// a false timeout.
158		timedOut := errors.Is(waitErr, context.DeadlineExceeded)
159		if shouldEmitSyntheticRunError(ctx, waitErr) {
160			synthEvent := reviewtypes.RunError{Err: waitErr}
161			buffer = append(buffer, synthEvent)
162			sawRunError = true
163			if firstRunErr == nil {
164				firstRunErr = waitErr
165			}
166			for _, sink := range sinks {
167				sink.AgentEvent(displayName, synthEvent)
168			}
169		}
170		status := classifyStatus(ctx, waitErr, eventOutcome{finishedSeen: finishedSeen, finishedOk: finishedOk, sawRunError: sawRunError})
171		runErr := waitErr
172		switch {
173		case timedOut:
174			status = reviewtypes.AgentStatusFailed
175			runErr = timedOutError(displayName, timeout)
176		case runErr == nil && status == reviewtypes.AgentStatusFailed:
177			runErr = agentRunFailureError(displayName, firstRunErr)
178		}
179	
180		summary := reviewtypes.RunSummary{
181			StartedAt:  started,
182			FinishedAt: finished,
183			Cancelled:  status == reviewtypes.AgentStatusCancelled,
184			AgentRuns: []reviewtypes.AgentRun{{
185				Name:      displayName,
186				AgentName: agentName,
187				Model:     modelName,
188				Status:    status,
189				Tokens:    tokens,
190				Buffer:    buffer,
191				StartedAt: started,
192				Duration:  finished.Sub(started),
193				Err:       runErr,
194			}},
195		}
196		summary = enrichRunSummary(ctx, cfg, summary)
197		for _, sink := range sinks {
198			sink.RunFinished(summary)
199		}
200		return summary, runErr
201	}
202	
203	func enrichRunSummary(ctx context.Context, cfg reviewtypes.RunConfig, summary reviewtypes.RunSummary) reviewtypes.RunSummary {
204		if cfg.EnrichSummary == nil {
205			return summary
206		}
207		return cfg.EnrichSummary(ctx, summary)
208	}
209	
210	func shouldEmitSyntheticRunError(ctx context.Context, waitErr error) bool {
211		if waitErr == nil {
212			return false
213		}
214		if ctx.Err() != nil {
215			return false
216		}
217		if errors.Is(waitErr, context.Canceled) || errors.Is(waitErr, context.DeadlineExceeded) {
218			return false
219		}
220		return true
221	}
222	
223	func agentRunFailureError(agent string, cause error) error {
224		if cause != nil {
225			return fmt.Errorf("review agent %s reported failure: %w", agent, cause)
226		}
227		return fmt.Errorf("review agent %s reported failure", agent)
228	}
229	
230	// eventOutcome summarises agent-level signals observed in the event stream.
231	// Used by classifyStatus to downgrade a process-level "exit 0" run that the
232	// parser flagged as torn (RunError + Finished{Success: false}) — a clean
233	// process exit doesn't imply a clean review result.
234	type eventOutcome struct {
235		finishedSeen bool // a Finished event was emitted (parser ran to completion)
236		finishedOk   bool // Finished.Success
237		sawRunError  bool // at least one RunError event was emitted
238	}
239	
240	// classifyStatus maps a process Wait error AND the event-stream outcome to
241	// a terminal AgentStatus.
242	//
243	// Order matters: ctx-cancelled + signal-killed delivers an *exec.ExitError
244	// with exit code -1, which would otherwise be misclassified as Failed.
245	// Check ctx.Err() FIRST so cancelled runs are reported as Cancelled.
246	// (Reference: PR #1018 commit 8e82e407a.)
247	//
248	// Event-level signals override process-level success: if the parser saw a
249	// RunError or emitted Finished{Success: false}, the run is Failed even when
250	// the process exits 0. This catches torn stdout streams the parser surfaces
251	// via RunError + Finished{Success: false} (CU3 fix-loop guarantee).
252	func classifyStatus(ctx context.Context, waitErr error, outcome eventOutcome) reviewtypes.AgentStatus {
253		if ctx.Err() != nil {
254			return reviewtypes.AgentStatusCancelled
255		}
256		if waitErr != nil {
257			return reviewtypes.AgentStatusFailed
258		}
259		// Process exited cleanly (exit 0). Honor agent-level signals.
260		if outcome.sawRunError {
261			return reviewtypes.AgentStatusFailed
262		}
263		if outcome.finishedSeen && !outcome.finishedOk {
264			return reviewtypes.AgentStatusFailed
265		}
266		return reviewtypes.AgentStatusSucceeded
267	}
