292	func defaultReviewProfileForInstalledAgents(
293		ctx context.Context,
294		profileName string,
295		installed []types.AgentName,
296		reviewerFor func(string) reviewtypes.AgentReviewer,
297	) (settings.ReviewProfileConfig, error) {
298		profileName = strings.TrimSpace(profileName)
299		if profileName == "" {
300			profileName = DefaultProfileName
301		}
302		installedNames := make([]string, 0, len(installed))
303		for _, name := range installed {
304			installedNames = append(installedNames, string(name))
305		}
306		sort.Strings(installedNames)
307	
308		agents := make(map[string]settings.ReviewConfig, len(installedNames))
309		for _, name := range installedNames {
310			if reviewerFor != nil && reviewerFor(name) == nil {
311				continue
312			}
313			cfg := defaultReviewAgentConfig(profileName, name)
314			if cfg.IsZero() {
315				continue
316			}
317			agents[name] = cfg
318		}
319		if len(agents) == 0 {
320			return settings.ReviewProfileConfig{}, errors.New("no agents with review runner adapters and hooks installed; run `entire configure --agent claude-code`, `entire configure --agent codex`, or `entire configure --agent gemini`")
321		}
322		profile := settings.ReviewProfileConfig{
323			Task:   profileTask(profileName, settings.ReviewProfileConfig{}),
324			Agents: agents,
325		}
326		if j, ok := defaultJudge(ctx, agents); ok {
327			profile.Judge = &settings.ReviewConfig{Agent: j.agent, Model: j.model}
328		}
329		return profile, nil
330	}
331	
332	func defaultReviewAgentConfig(profileName, agentName string) settings.ReviewConfig {
333		focus := defaultProfileFocus(profileName)
334		switch agentName {
335		case string(agent.AgentNameClaudeCode):
336			if strings.EqualFold(profileName, "security") {
337				return settings.ReviewConfig{Skills: []string{"/security-review"}}
338			}
339			return settings.ReviewConfig{Skills: []string{"/review"}, Prompt: focus}
340		case string(agent.AgentNameCodex):
341			return settings.ReviewConfig{Skills: []string{"/review"}, Prompt: focus}
342		case string(agent.AgentNameGemini):
343			prompt := "Review the change according to the profile task."
344			if focus != "" {
345				prompt += " " + focus
346			}
347			return settings.ReviewConfig{Prompt: prompt}
348		default:
349			return settings.ReviewConfig{}
350		}
351	}
352	
353	func defaultProfileFocus(profileName string) string {
354		switch strings.ToLower(strings.TrimSpace(profileName)) {
355		case "security":
356			return "Focus specifically on security issues."
357		case "accessibility", "a11y":
358			return "Focus specifically on accessibility issues."
359		default:
360			return ""
361		}
362	}
363	
364	// defaultJudge auto-selects a consolidating judge from the configured
365	// inspectors: it prefers claude-code, then codex, then gemini, and otherwise
366	// takes the first inspector that can write a verdict (text generation). ok is
367	// false when no inspector can.
368	func defaultJudge(ctx context.Context, configured map[string]settings.ReviewConfig) (judgeSpec, bool) {
369		for _, preferred := range []string{string(agent.AgentNameClaudeCode), string(agent.AgentNameCodex), string(agent.AgentNameGemini)} {
370			for _, workerName := range sortedReviewConfigKeys(configured) {
371				cfg := configured[workerName]
372				if reviewAgentName(workerName, cfg) == preferred && agentSupportsTextGeneration(ctx, preferred) {
373					return judgeSpec{agent: preferred, model: strings.TrimSpace(cfg.Model)}, true
374				}
375			}
376		}
377		for _, workerName := range sortedReviewConfigKeys(configured) {
378			cfg := configured[workerName]
379			if name := reviewAgentName(workerName, cfg); agentSupportsTextGeneration(ctx, name) {
380				return judgeSpec{agent: name, model: strings.TrimSpace(cfg.Model)}, true
381			}
382		}
383		return judgeSpec{}, false
384	}
385	
386	func sortedReviewConfigKeys(configured map[string]settings.ReviewConfig) []string {
387		names := make([]string, 0, len(configured))
388		for name := range configured {
389			names = append(names, name)
390		}
391		sort.Strings(names)
392		return names
393	}
394	
395	func agentSupportsTextGeneration(_ context.Context, name string) bool {
396		ag, err := agent.Get(types.AgentName(name))
397		if err != nil {
398			return false
399		}
400		_, ok := agent.AsTextGenerator(ag)
401		return ok
402	}
403	
404	// reviewSettingsScope selects which settings file a review profile is written
405	// to. Both files are read and merged by settings.Load; the scope only decides
406	// where new profiles are persisted.
407	type reviewSettingsScope int
408	
409	const (
410		// reviewScopeProject writes to .entire/settings.json (shared, committed).
411		reviewScopeProject reviewSettingsScope = iota
412		// reviewScopeLocal writes to .entire/settings.local.json (per-developer).
413		reviewScopeLocal
414	)
415	
416	// file returns the settings filename this scope writes to.
417	func (s reviewSettingsScope) file() string {
418		if s == reviewScopeLocal {
419			return settings.EntireSettingsLocalFile
420		}
421		return settings.EntireSettingsFile
422	}
423	
424	func saveDefaultReviewProfile(ctx context.Context, profileName string, profile settings.ReviewProfileConfig, scope reviewSettingsScope) error {
425		return saveReviewProfile(ctx, profileName, profile, false, scope)
426	}
427	
428	// saveReviewProfile persists one profile into the chosen settings file via a
429	// raw read-modify-write so unrelated keys (and other profiles) are preserved.
430	func saveReviewProfile(ctx context.Context, profileName string, profile settings.ReviewProfileConfig, makeDefault bool, scope reviewSettingsScope) error {
431		path, raw, err := loadReviewSettingsRaw(ctx, scope)
432		if err != nil {
433			return err
434		}
435		profiles, err := decodeRawReviewProfiles(raw)
436		if err != nil {
437			return err
438		}
439		profiles[profileName] = profile
440		defaultName := decodeRawString(raw, "review_default_profile")
441		if makeDefault || strings.TrimSpace(defaultName) == "" {
442			defaultName = profileName
443		}
444		return writeRawReviewProfiles(path, raw, profiles, defaultName)
445	}
446	
447	// loadReviewSettingsRaw reads the raw JSON object for the chosen settings file.
448	func loadReviewSettingsRaw(ctx context.Context, scope reviewSettingsScope) (string, map[string]json.RawMessage, error) {
449		var (
450			path string
451			raw  map[string]json.RawMessage
452			err  error
453		)
454		if scope == reviewScopeLocal {
455			path, raw, _, err = settings.LoadLocalRaw(ctx)
456		} else {
457			path, raw, _, err = settings.LoadProjectRaw(ctx)
458		}
459		if err != nil {
460			return "", nil, fmt.Errorf("load %s before save: %w", scope.file(), err)
461		}
462		if raw == nil {
463			raw = map[string]json.RawMessage{}
464		}
465		return path, raw, nil
466	}
467	
468	func decodeRawReviewProfiles(raw map[string]json.RawMessage) (map[string]settings.ReviewProfileConfig, error) {
469		profiles := map[string]settings.ReviewProfileConfig{}
470		if msg, ok := raw["review_profiles"]; ok && len(msg) > 0 {
471			if err := json.Unmarshal(msg, &profiles); err != nil {
472				return nil, fmt.Errorf("parse existing review_profiles: %w", err)
473			}
474			if profiles == nil {
475				profiles = map[string]settings.ReviewProfileConfig{}
476			}
477		}
478		return profiles, nil
479	}
480	
481	func decodeRawString(raw map[string]json.RawMessage, key string) string {
482		if msg, ok := raw[key]; ok && len(msg) > 0 {
483			var s string
484			if err := json.Unmarshal(msg, &s); err == nil {
485				return s
486			}
487		}
488		return ""
489	}
490	
491	func writeRawReviewProfiles(path string, raw map[string]json.RawMessage, profiles map[string]settings.ReviewProfileConfig, defaultName string) error {
492		profilesJSON, err := json.Marshal(profiles)
493		if err != nil {
494			return fmt.Errorf("encode review_profiles: %w", err)
495		}
496		raw["review_profiles"] = profilesJSON
497		if strings.TrimSpace(defaultName) != "" {
498			defJSON, err := json.Marshal(defaultName)
499			if err != nil {
500				return fmt.Errorf("encode review_default_profile: %w", err)
501			}
502			raw["review_default_profile"] = defJSON
503		}
504		// SaveProjectRaw writes the given path atomically (temp file + rename in the
505		// same dir) but does not create the directory, so ensure .entire/ exists
506		// for repos that haven't been enabled yet.
507		if dir := filepath.Dir(path); dir != "" {
508			if err := os.MkdirAll(dir, 0o750); err != nil {
509				return fmt.Errorf("create settings dir %s: %w", dir, err)
510			}
511		}
512		// SaveProjectRaw is path-generic despite the name, so it also serves the
513		// local settings file.
514		if err := settings.SaveProjectRaw(path, raw); err != nil {
515			return fmt.Errorf("write %s: %w", path, err)
516		}
517		return nil
518	}
