func maybePostReviewToTrail(
	ctx context.Context,
	out io.Writer,
	deps Deps,
	outputMode, profileName string,
	summary reviewtypes.RunSummary,
	aggregateOutput string,
) {
	if outputMode != ReviewOutputTrail || summary.Cancelled {
		return
	}
	verdict := strings.TrimSpace(aggregateOutput)
	if verdict == "" {
		verdict = combinedReviewNarratives(summary)
	}
	if verdict == "" {
		fmt.Fprintln(out, "Nothing to report, so nothing was posted to the trail.")
		return
	}
	if deps.PostReviewToTrail == nil {
		fmt.Fprintln(out, "Trail output is not available here; the review was kept local.")
		return
	}
	// On success the hook prints its own confirmation and trail link.
	if err := deps.PostReviewToTrail(ctx, out, profileName, verdict); err != nil {
		fmt.Fprintf(out, "Could not post the review to the trail: %v\n", err)
	}
}

// combinedReviewNarratives joins the inspectors' narratives into one document,
// used as the trail-posting body for single-inspector runs (which have no
// synthesized verdict) and as a fallback when synthesis produced nothing.
func combinedReviewNarratives(summary reviewtypes.RunSummary) string {
	var b strings.Builder
	for _, run := range usableAgentRuns(summary) {
		narrative := joinAssistantText(run.Buffer)
		if narrative == "" {
			continue
		}
		if b.Len() > 0 {
			b.WriteString("\n\n")
		}
		fmt.Fprintf(&b, "## %s\n\n%s", run.Name, narrative)
	}
	return strings.TrimSpace(b.String())
}

func writePostReviewManifest(
	ctx context.Context,
	out io.Writer,
	worktreeRoot string,
	headSHA string,
	summary reviewtypes.RunSummary,
	aggregateOutput string,
) {
	if summary.Cancelled || len(summary.AgentRuns) == 0 {
		return
	}
	manifest, states, err := localReviewManifestFromCurrentState(ctx, worktreeRoot, headSHA, summary, aggregateOutput)
	if err != nil {
		logging.Debug(ctx, "review manifest not written", slog.String("error", err.Error()))
		warnManifestNotWritten(out, "could not load session state: "+err.Error())
		return
	}
	if len(manifest.Sources) == 0 {
		reason, sentinel := explainEmptyManifest(worktreeRoot, headSHA, summary, states)
		if sentinel {
			// Matcher and explainer have drifted — the matcher rejected
			// every tagged session for a reason none of the explainer's
			// filters cover. Surface at Warn so this gets noticed without
			// requiring debug logging.
			logging.Warn(ctx, "review manifest matcher/explainer drift detected",
				slog.String("reason", reason),
				slog.Int("tagged_state_count", len(states)),
				slog.Int("agent_run_count", len(summary.AgentRuns)))
		} else {
			logging.Debug(ctx, "review manifest not written: no matching review sessions",
				slog.String("reason", reason))
		}
		warnManifestNotWritten(out, reason)
		return
	}
	if err := writeLocalReviewManifest(ctx, manifest); err != nil {
		logging.Debug(ctx, "review manifest write failed", slog.String("error", err.Error()))
		warnManifestNotWritten(out, "write to disk failed: "+err.Error())
		return
	}
	writeReviewCompletionFooter(out, manifest)
}

	ctx context.Context,
	cmd *cobra.Command,
	profileName string,
	profile settings.ReviewProfileConfig,
	launchableEligible []AgentChoice,
	judge judgeSpec,
	outputMode string,
	timeout time.Duration,
	baseOverride string,
	perRunPrompt string,
	deps Deps,
	out io.Writer,
) error {
	// Resolve worktree root and HEAD SHA for scope detection.
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		cmd.SilenceUsage = true
		return fmt.Errorf("resolve worktree root: %w", err)
	}
	headSHA, shaErr := currentHeadSHA(ctx, worktreeRoot)
	if shaErr != nil {
		cmd.SilenceUsage = true
		return fmt.Errorf("resolve HEAD: %w", shaErr)
	}

	if proceed, guardErr := confirmReReviewOrProceed(ctx, out, deps); guardErr != nil {
		fmt.Fprintln(out, "prompt cancelled")
		return deps.NewSilentError(guardErr)
	} else if !proceed {
		fmt.Fprintln(out, "Review cancelled.")
		return nil
	}

	scopeBaseRef, scopeErr := detectScope(ctx, worktreeRoot, baseOverride, out)
	if scopeErr != nil {
		cmd.SilenceUsage = true
		return scopeErr
	}
	checkpointContext := ""
	if deps.ReviewCheckpointContext != nil {
		checkpointContext = deps.ReviewCheckpointContext(ctx, worktreeRoot, scopeBaseRef)
	}
	reviewers := make([]reviewtypes.AgentReviewer, 0, len(launchableEligible))
	for _, choice := range launchableEligible {
		workerName := choice.Name
		agentCfg := profile.Agents[workerName]
		agentName := reviewAgentName(workerName, agentCfg)
		if len(agentCfg.Skills) > 0 {
			ag, agErr := agent.Get(types.AgentName(agentName))
			if agErr != nil {
				return fmt.Errorf("resolve agent %s: %w", agentName, agErr)
			}
			if err := VerifyConfiguredSkillsInstalled(ctx, ag, agentCfg); err != nil {
				cmd.SilenceUsage = true
				fmt.Fprintln(cmd.ErrOrStderr(), err.Error())
				return deps.NewSilentError(err)
			}
		}
		reviewer := deps.ReviewerFor(agentName)
		if reviewer == nil {
			cmd.SilenceUsage = true
			return deps.NewSilentError(fmt.Errorf("agent %q has no review runner adapter but appeared in eligible list", agentName))
		}
		reviewers = append(reviewers, &perAgentConfiguredReviewer{
			name:  reviewWorkerLabel(workerName, agentCfg),
			inner: reviewer,
			cfg: runConfigWithReviewConfig(reviewtypes.RunConfig{
				ProfileName:       profileName,
				Task:              profile.Task,
				PerRunPrompt:      perRunPrompt,
				ScopeBaseRef:      scopeBaseRef,
				CheckpointContext: checkpointContext,
				StartingSHA:       headSHA,
			}, agentCfg),
		})
	}

	runCtx, cancelRun := context.WithCancel(ctx)
	defer cancelRun()

	agentNames := make([]string, len(reviewers))
	for i, r := range reviewers {
		agentNames[i] = r.Name()
	}
	aggregateOutput := ""

	// The single consolidating judge (resolved and validated by the caller)
	// turns the inspectors' reports into the final verdict.
	var synthProvider SynthesisProvider = AgentSynthesisProvider{AgentName: judge.agent, Model: judge.model}
	masterLabel := judgeLabel(judge)
	sinks := composeMultiAgentSinks(multiAgentSinkInputs{
		out:               out,
		isTTY:             interactive.IsTerminalWriter(out) && interactive.CanPromptInteractively(),
		canPrompt:         interactive.CanPromptInteractively(),
		agentNames:        agentNames,
		cancelRun:         cancelRun,
		runContext:        runCtx,
		synthesisProvider: synthProvider,
		perRunPrompt:      perRunPrompt,
		profileName:       profileName,
		task:              profile.Task,
		masterName:        masterLabel,
		autoSynthesis:     true,
		onSynthesisResult: func(result string) {
			aggregateOutput = result
		},
	})
	if tuiSink, ok := findTUISink(sinks); ok {
		tuiSink.Start()
		defer tuiSink.Wait()
	}

	summary, waitErr := RunMulti(runCtx, reviewers, reviewtypes.RunConfig{
		EnrichAgentRun:   reviewAgentRunTokenEnricher(worktreeRoot, headSHA),
		InspectorTimeout: timeout,
	}, sinks)
	writePostReviewManifest(ctx, out, worktreeRoot, headSHA, summary, aggregateOutput)
	maybePostReviewToTrail(ctx, out, deps, outputMode, profileName, summary, aggregateOutput)
	if waitErr != nil && runCtx.Err() == nil && ctx.Err() == nil {
		return fmt.Errorf("review run: %w", waitErr)

// Package review — see env.go for package-level rationale.
//
// synthesis_sink.go provides SynthesisSink, an opt-in Sink that prompts the
// user (y/N, default N) after all agents finish, then asks a configured
// summary provider to synthesize a unified verdict across the per-agent
// narratives. Skipped silently in non-TTY mode, on cancellation, or when
// fewer than 2 agents produced usable output.
//
// Composition: appended AFTER DumpSink in TTY-mode sink slices, so the
// y/N prompt appears below the per-agent narrative dump.
package review

import (
	"context"
	"fmt"
	"io"
	"log/slog"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	agenttypes "github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/mdrender"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
	"github.com/entireio/cli/cmd/entire/cli/uiform"
)

// SynthesisProvider abstracts the LLM call that produces the cross-agent
// verdict. Injected via Deps so tests can stub the provider call without a
// real API roundtrip. Production wiring (in review_bridge.go) calls into
// the same provider entire explain uses.
type SynthesisProvider interface {
	// Synthesize takes the composed synthesis prompt and returns the
	// verdict text. Errors are surfaced to the caller; SynthesisSink
	// degrades gracefully on error rather than failing the run.
	Synthesize(ctx context.Context, prompt string) (string, error)
}

// AgentSynthesisProvider asks a named agent's text-generation API to produce
// the final report. This is the profile-native master implementation used by
// `entire review`: workers run as review sessions, while the master is an
// isolated text-generation call so it consolidates reports without creating a
// second review worker session.
type AgentSynthesisProvider struct {
	AgentName string
	Model     string
}

func (p AgentSynthesisProvider) Synthesize(ctx context.Context, prompt string) (string, error) {
	ag, err := agent.Get(agenttypes.AgentName(p.AgentName))
	if err != nil {
		return "", fmt.Errorf("resolve master agent %s: %w", p.AgentName, err)
	}
	tg, ok := agent.AsTextGenerator(ag)
	if !ok {
		return "", fmt.Errorf("master agent %s does not support text generation", p.AgentName)
	}
	return tg.GenerateText(ctx, prompt, p.Model) //nolint:wrapcheck // caller owns display
}

// SynthesisSink composes a multi-agent verdict by calling a configured
// provider after the run finishes. In normal profile-native `entire review`
// runs this is the profile's master adjudication phase: Auto is true and
// Provider is the profile master, so the master report is produced without a
// y/N prompt. The legacy opt-in path (Auto false) keeps the prompted-synthesis
// behavior. AgentEvent is a no-op; all work happens in RunFinished.
type SynthesisSink struct {
	Provider        SynthesisProvider
	Writer          io.Writer
	InputTTY        bool // true if stdin can prompt the user
	PromptYN        func(ctx context.Context, question string, def bool) (bool, error)
	PerRunPrompt    string // if non-empty, included in the synthesis prompt for context
	ProfileName     string
	Task            string
	MasterName      string
	Auto            bool            // when true, run without a y/N prompt (profile-native final report)
	RunContext      context.Context // optional; nil falls back to context.Background()
	ProviderTimeout time.Duration   // optional; zero uses defaultSynthesisProviderTimeout
	OnResult        func(result string)
}

// Compile-time interface check.
var _ reviewtypes.Sink = SynthesisSink{}

const defaultSynthesisProviderTimeout = 2 * time.Minute

// AgentEvent is a no-op; SynthesisSink only acts in RunFinished.
func (SynthesisSink) AgentEvent(_ string, _ reviewtypes.Event) {}

// RunFinished optionally synthesizes a cross-agent verdict.
//
// Skip silently when:
//   - stdin isn't a TTY (s.InputTTY == false)
//   - the run was cancelled (summary.Cancelled)
//   - fewer than 2 agents produced usable output (status Succeeded or Failed
//     with non-empty narrative buffer)
//
// In profile-native mode (Auto=true), the master phase is mandatory and runs
// without a y/N prompt. In legacy sink mode (Auto=false), prompt y/N (default
// N). On provider failure: print "final report unavailable: <err>" with the
// underlying error; user can still commit.
func (s SynthesisSink) RunFinished(summary reviewtypes.RunSummary) {
	if summary.Cancelled {
		return
	}
	if usableAgentCount(summary) < 2 {
		return
	}

	ctx := s.runContext()
	if !s.Auto {
		if !s.InputTTY {
			return
		}
		promptFn := s.PromptYN
		if promptFn == nil {
			promptFn = realPromptYN
		}

		yes, err := promptFn(ctx, "Synthesize a unified verdict across all agent reviews?", false)
		if err != nil {
			// huh form errors (terminal-resize anomalies, stdin EOF, stub
			// failures) shouldn't block the user from committing — they get the
			// same silent skip as a "no" answer. Logged at debug for diagnostics.
			logging.Debug(ctx, "synthesis prompt error",
				slog.String("error", err.Error()))
			return
		}
		if !yes {
			return
		}
	}

	synthesisPrompt := composeSynthesisPrompt(summary, s.PerRunPrompt, s.ProfileName, s.Task)
	providerCtx, cancelProvider := s.providerContext()
	defer cancelProvider()
	if s.Auto {
		if s.MasterName != "" {
			fmt.Fprintf(s.Writer, "Generating final report with %s...\n", s.MasterName)
		} else {
			fmt.Fprintln(s.Writer, "Generating final report...")
		}
	} else {
		fmt.Fprintln(s.Writer, "Generating summary...")
	}
	result, provErr := s.Provider.Synthesize(providerCtx, synthesisPrompt)
	if provErr != nil {
		if s.Auto {
			fmt.Fprintf(s.Writer, "final report unavailable: %v\n", provErr)
		} else {
			fmt.Fprintf(s.Writer, "synthesis unavailable: %v\n", provErr)
		}
		return
	}
	if s.OnResult != nil {
		s.OnResult(result)
	}
	// The synthesis verdict is markdown — render it through the same palette
	// dispatch / DumpSink use, so multi-agent reviews finish with a visually
	// consistent block. Non-TTY writers receive raw markdown unchanged.
	//
	// Use Fprint (not Fprintln): mdrender.Render returns glamour output that
	// already ends with a newline, and the raw-markdown fallback path has its
	// own terminal newline from the LLM response. Adding Fprintln would double
	// the trailing blank line.
	rendered, err := mdrender.RenderForWriter(s.Writer, result)
	if err != nil {
		rendered = result
	}
	fmt.Fprint(s.Writer, rendered)
}

func (s SynthesisSink) runContext() context.Context {
	if s.RunContext != nil {
		return s.RunContext
	}
	return context.Background()
}

func (s SynthesisSink) providerContext() (context.Context, context.CancelFunc) {
	timeout := s.ProviderTimeout
	if timeout <= 0 {
		timeout = defaultSynthesisProviderTimeout
	}
	return context.WithTimeout(s.runContext(), timeout)
}

// usableAgentCount returns the number of agents that produced usable narrative
// output (non-empty AssistantText in their buffer). Used to determine whether
// synthesis is worth offering.
func usableAgentCount(summary reviewtypes.RunSummary) int {
	return len(usableAgentRuns(summary))
}

// realPromptYN is the production y/N prompt; delegates to uiform.PromptYN
// so the review and investigate packages share one implementation.
func realPromptYN(ctx context.Context, question string, def bool) (bool, error) {
	return uiform.PromptYN(ctx, question, def) //nolint:wrapcheck // uiform already wraps
}

